from collections import deque
H,W=len(grid),len(grid[0]); seen=set(); q=deque()
for r in range(H):
 for c in range(W):
  if (r in (0,H-1) or c in (0,W-1)) and grid[r][c]==1: seen.add((r,c));q.append((r,c))
while q:
 r,c=q.popleft()
 for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
  if 0<=rr<H and 0<=cc<W and grid[rr][cc]==1 and (rr,cc) not in seen:
   seen.add((rr,cc));q.append((rr,cc))
inside=[(r,c) for r in range(H) for c in range(W) if grid[r][c]==1 and (r,c) not in seen]
print(len(inside), inside)
# list connected components enclosed
s=set(inside); comps=[]
while s:
 st=s.pop(); co={st}; dq=[st]
 while dq:
  r,c=dq.pop()
  for n in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
   if n in s: s.remove(n);co.add(n);dq.append(n)
 comps.append(co)
print([(len(x), (min(r for r,c in x), max(r for r,c in x), min(c for r,c in x), max(c for r,c in x))) for x in comps])
